/**
 * Fixed password fixtures for password-rules.test.ts (review of a9ddf56, 28 Nov 2026).
 * Not a test file (outside __tests__).
 *
 * - HOSTILE: 288 predictable passwords the independent re-test built (repeats, padding,
 *   swaps, keyboard walks, dates and phones, the email and name, the app and exam words,
 *   Unicode tricks, long words, clichés, Filipino passwords). Stored scrambled (letters
 *   ROT13, digits ROT5) because some are rude; unscramble with `unscramble`.
 * - HOSTILE_GROUPS: the same, by kind (scrambled).
 * - GOOD: 62 passphrases that must pass (the 70 of round 2 less 8 clichés; see below).
 * - OFF_LIST_WORDS: 3,000 English words ranked AFTER the bundled 100,000 in the pinned
 *   SecLists source (so the test is not circular), scrambled.
 * - ORDINARY_WORDS: ordinary English words (in the dictionary and in the source's top 100,000,
 *   3 to 8 letters), scrambled: random triples of them must pass.
 * - KNOWN_ACCEPTS: every hostile password that still passes, with the reason. The test
 *   fails if any other one passes, so this list can only get shorter.
 */

const rot = (s: string) => Array.from(s, (ch) => { const c = ch.charCodeAt(0); return c >= 97 && c <= 122 ? String.fromCharCode(((c - 97 + 13) % 26) + 97) : c >= 48 && c <= 57 ? String.fromCharCode(((c - 48 + 5) % 10) + 48) : ch; }).join('');
export const unscramble = (l: readonly string[]) => l.map(rot);

